import { t, ui, locale, bindText, onLanguageChange } from './i18n.js';
const html=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const states={preview:'Anteprima da controllare',publishing:'Pubblicazione in corso',published:'Bozza PR pubblicata',uncertain:'Esito da verificare'};
const help=(label,text)=>ui`<details class="github-help"><summary aria-label="Aiuto: ${html(label)}">?</summary><p>${html(text)}</p></details>`;
const safeUrl=value=>{try{const url=new URL(value);return url.protocol==='https:'&&url.hostname==='github.com'&&!url.username&&!url.password?url.href:null;}catch{return null;}};
const field=(label,name,value='',{area=false,max=2000,required=true,type='text'}={})=>ui`<div class="ops-field"><label for="github-${name}">${html(label)}</label>${area?ui`<textarea id="github-${name}" name="${name}" rows="5" maxlength="${max}"${required?' required':''}>${html(value)}</textarea>`:ui`<input id="github-${name}" name="${name}" type="${type}" value="${html(value)}" maxlength="${max}"${required?' required':''} autocomplete="${type==='password'?'new-password':'off'}"${type==='password'?' spellcheck="false" data-github-secret':''}>`}</div>`;

export function createGithubPanel({host,toast=()=>{},onSourcesChanged=()=>{}}={}){
  let snapshot={connections:[],publications:[]},context={scopeId:'business',scopes:[],runs:[],filter:'current'},visible=false,loaded=false,loading=false,saving=false,busy=false,disposed=false,error='',generation=0,view=null,loadPromise=null;
  let languageView=null;
  const controllers=new Set(),dialog=document.createElement('dialog');
  dialog.id='github-dialog';dialog.className='ops-dialog github-dialog';dialog.setAttribute('aria-labelledby','github-dialog-title');document.body.append(dialog);
  const locked=()=>busy||saving||loading||disposed;
  const scopeName=id=>context.scopes.find(scope=>scope.id===id)?.name||id;
  const connection=id=>snapshot.connections.find(item=>item.id===id);
  const publication=id=>snapshot.publications.find(item=>item.id===id);
  const approved=run=>run.status==='completed'&&run.decision?.status==='approved';
  const runFor=id=>context.runs.find(run=>run.id===id);
  const eligible=(scopeId,publish=false)=>snapshot.connections.filter(item=>item.tokenConfigured&&item.scopeIds.includes(scopeId)&&(!publish||item.allowPublish));
  function accept(value){if(!value||!Array.isArray(value.connections)||!Array.isArray(value.publications))throw Error(t('Il collegamento GitHub non ha restituito uno stato valido.'));snapshot=value;}
  async function request(path,body){
    const controller=new AbortController();controllers.add(controller);
    try{const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body),signal:controller.signal}:{cache:'no-store',signal:controller.signal});let value;try{value=await response.json();}catch{throw Error(t('La risposta dello studio non è leggibile. Aggiorna lo stato prima di riprovare.'));}if(!response.ok)throw Object.assign(Error(value.error||(response.status===404?t('GitHub non è disponibile in questa versione del server.'):t('La richiesta GitHub non è riuscita.'))),{status:response.status});return value;}finally{controllers.delete(controller);}
  }
  async function mutation(action,payload){const value=await request('/api/github',{action,payload});accept(value.snapshot);render();return value.result;}
  function locks(){host.setAttribute('aria-busy',String(loading||saving));for(const parent of [host,dialog]){parent.querySelectorAll('[data-github-mutation],button[type="submit"]').forEach(el=>el.disabled=locked());parent.querySelectorAll('[data-github-action="reload"]').forEach(el=>el.disabled=loading||saving);}}
  function render(){
    if(!visible)return;
    const connections=snapshot.connections.filter(item=>context.filter==='all'||item.scopeIds.includes(context.scopeId));
    const publications=snapshot.publications.filter(item=>context.filter==='all'||item.scopeId===context.scopeId);
    host.innerHTML=ui`<div class="github-heading"><div><div class="github-title"><h3>Dal tuo repository a una PR.</h3>${help(t('Permessi GitHub'),t('Ogni connessione è limitata a repository e ambiti espliciti. Il token GitHub è separato dalle credenziali AI e resta cifrato sul server. La pubblicazione richiede una patch approvata, una nuova anteprima e un tuo avvio esplicito.'))}</div><p>Leggi anche repository privati e pubblica le modifiche che hai revisionato.</p></div><button type="button" class="ops-button" data-github-action="reload">Aggiorna</button></div><div class="github-tools"><button type="button" class="ops-button is-primary" data-github-action="connect" data-github-mutation>＋ Collega GitHub</button><button type="button" class="ops-button" data-github-action="import" data-github-mutation>Acquisisci un file</button><button type="button" class="ops-button" data-github-action="preview" data-github-mutation>Prepara una PR</button></div>${error?ui`<p class="github-notice is-error" role="alert">${html(error)}</p>`:''}${loading&&!loaded?ui('<p class="github-empty" role="status">Caricamento dei collegamenti…</p>'):ui`<div class="github-grid">${connections.map(item=>ui`<article class="github-card"><div class="github-card-top"><strong>${html(item.name)}</strong><span class="github-state">${item.allowPublish?t('Lettura e PR'):t('Lettura')}</span></div><p>${item.tokenConfigured?t('Credenziale configurata'):t('Credenziale da configurare')}</p><ul class="github-repos">${item.repositories.map(repo=>ui`<li><code>${html(repo)}</code></li>`).join('')}</ul><p class="github-scopes">${item.scopeIds.map(scopeName).map(html).join(' · ')}</p><div class="github-card-actions"><button type="button" class="ops-button" data-github-action="edit" data-id="${html(item.id)}" data-github-mutation>Modifica</button><button type="button" class="ops-button" data-github-action="inspect" data-id="${html(item.id)}" data-github-mutation>Verifica accesso</button><button type="button" class="ops-text-button" data-github-action="disconnect" data-id="${html(item.id)}" data-github-mutation>Scollega</button></div></article>`).join('')||ui('<div class="github-empty"><strong>Nessuna connessione per questo ambito.</strong><p>Collega una credenziale GitHub e scegli i repository accessibili allo studio.</p></div>')}</div><section class="github-publications"><h3>Anteprime e pubblicazioni</h3>${publications.length?publications.map(item=>ui`<button type="button" class="github-publication" data-github-action="publication" data-id="${html(item.id)}"><span><strong>${html(item.title)}</strong><small>${html(item.repository)} · ${html(scopeName(item.scopeId))}</small></span><span class="github-state${item.status==='uncertain'||item.baseChanged||item.reviewRequired?' is-warning':''}">${html(item.baseChanged||item.reviewRequired?t('PR da rivedere'):t(states[item.status]||item.status))}</span><span aria-hidden="true">↗</span></button>`).join(''):ui('<p class="github-empty">Le anteprime delle patch approvate compariranno qui.</p>')}</section>`}<p class="github-footnote">Le letture contattano GitHub. La pubblicazione crea un ramo dedicato e una pull request in bozza, senza effettuare il merge.</p>`;locks();
  }
  function load(){if(loadPromise)return loadPromise;if(saving||disposed)return Promise.resolve();const version=++generation;loading=true;error='';render();loadPromise=(async()=>{try{const value=await request('/api/github');if(version===generation&&!disposed){accept(value);loaded=true;}}catch(e){if(e.name!=='AbortError'&&version===generation)error=e.message;}finally{loadPromise=null;if(version===generation){loading=false;render();}}})();return loadPromise;}
  function shell(title,body,footer){dialog.innerHTML=ui`<div class="ops-dialog-heading"><div><div class="eyebrow">COLLEGAMENTO GITHUB</div><h2 id="github-dialog-title">${html(title)}</h2></div><button type="button" class="ops-icon" data-github-close aria-label="Chiudi finestra">✕</button></div>${body}<div class="ops-dialog-footer">${footer||ui('<button type="button" class="ops-button" data-github-close>Chiudi</button>')}</div>`;if(!dialog.open)dialog.showModal();locks();}
  function form(title,body,label,submit,{after}={}){
    view={kind:'form'};shell(title,ui`<form id="github-form"><div class="ops-form-body">${body}</div><p class="ops-form-error" role="alert" hidden></p></form>`,ui`<button type="button" class="ops-button" data-github-close>Annulla</button><button type="submit" form="github-form" class="ops-button is-primary" data-github-mutation>${html(label)}</button>`);
    dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();if(locked())return;const el=event.currentTarget;if(!el.reportValidity())return;const data=new FormData(el),box=dialog.querySelector('.ops-form-error');saving=true;box.hidden=true;locks();dialog.querySelectorAll('[data-github-secret]').forEach(input=>input.value='');try{const result=await submit(data);if(!disposed){dialog.close();saving=false;after?.(result);}}catch(e){if(!disposed){box.textContent=e.status===409?ui`${e.message} Aggiorna lo stato prima di una nuova operazione.`:e.message;box.hidden=false;}}finally{data.delete('token');saving=false;locks();}});
  }
  function edit(item){languageView=()=>edit(item);
    if(locked())return;
    const scopes=context.scopes.filter(scope=>!['shared','archive'].includes(scope.kind));
    form(item?t('Rivedi il collegamento'):t('Collega un account GitHub'),ui`${field(t('Nome del collegamento'),'name',item?.name||t('GitHub personale'),{max:100})}${field(item?.tokenConfigured?t('Nuovo token · lascia vuoto per conservare quello salvato'):t('Token GitHub con permessi limitati'),'token','',{type:'password',max:1000,required:!item?.tokenConfigured})}<p class="ops-hint">Usa un token con accesso soltanto ai repository scelti. Per leggere file occorre Contents: read; per pubblicare servono Contents e Pull requests: write. Il token non viene mostrato dopo il salvataggio e non viene inviato agli agenti.</p>${field(t('Repository autorizzati · uno per riga'),'repositories',item?.repositories.join('\n')||'',{area:true,max:5000})}<p class="ops-hint">Formato proprietario/repository, per esempio Riccardo-RG/fuori-studio. Nessun accesso implicito agli altri repository dell’account.</p><fieldset class="github-scope-fields"><legend>Ambiti autorizzati</legend>${scopes.map(scope=>ui`<label class="ops-check"><input type="checkbox" name="scopeIds" value="${html(scope.id)}"${(item?.scopeIds||[context.scopeId]).includes(scope.id)?' checked':''}><span>${html(scope.name)}</span></label>`).join('')}</fieldset><label class="ops-check github-consent"><input type="checkbox" name="allowPublish"${item?.allowPublish?' checked':''}><span>Consenti la pubblicazione di PR<small>Ogni pubblicazione richiederà comunque una patch approvata e il tuo avvio dall’anteprima.</small></span></label>`,t('Salva collegamento'),async data=>{const scopeIds=data.getAll('scopeIds'),repositories=data.get('repositories').split(/[\n,]/).map(value=>value.trim()).filter(Boolean);if(!scopeIds.length)throw Error(t('Scegli almeno un ambito.'));if(!repositories.length)throw Error(t('Indica almeno un repository.'));const token=data.get('token').trim();return mutation('save',{...(item?{id:item.id,expectedVersion:item.version}:{}),name:data.get('name').trim(),...(token?{token}:{}),scopeIds,repositories,allowPublish:data.has('allowPublish')});},{after:()=>toast(t('Collegamento GitHub salvato. Verifica l’accesso al repository prima di usarlo.'))});
  }
  function targetFields({scopeId=context.scopeId,publish=false,chosen}={}){const options=eligible(scopeId,publish),selected=options.find(item=>item.id===chosen)||options[0];return ui`<div class="ops-form-grid"><div class="ops-field"><label for="github-connection">Collegamento autorizzato</label><select id="github-connection" name="connectionId" required>${options.map(item=>ui`<option value="${html(item.id)}"${item===selected?' selected':''}>${html(item.name)}</option>`).join('')}</select></div><div class="ops-field"><label for="github-repository">Repository</label><select id="github-repository" name="repository" required>${(selected?.repositories||[]).map(repo=>ui`<option value="${html(repo)}">${html(repo)}</option>`).join('')}</select></div></div>`;}
  function wireTarget(){dialog.querySelector('[name="connectionId"]')?.addEventListener('change',event=>{const repos=connection(event.target.value)?.repositories||[];dialog.querySelector('[name="repository"]').innerHTML=repos.map(repo=>ui`<option value="${html(repo)}">${html(repo)}</option>`).join('');});}
  function inspect(item){languageView=()=>inspect(item);const scopes=item.scopeIds.filter(id=>context.scopes.some(scope=>scope.id===id));const selected=scopes.includes(context.scopeId)?context.scopeId:scopes[0];if(!selected){toast(t('Questo collegamento non ha un ambito operativo disponibile.'));return;}form(t('Verifica la lettura del repository'),ui`<p class="ops-form-intro">La verifica contatta GitHub usando la credenziale salvata.</p><div class="ops-field"><label for="github-inspect-scope">Ambito</label><select id="github-inspect-scope" name="scopeId">${scopes.map(id=>ui`<option value="${html(id)}"${id===selected?' selected':''}>${html(scopeName(id))}</option>`).join('')}</select></div><div class="ops-field"><label for="github-inspect-repo">Repository</label><select id="github-inspect-repo" name="repository">${item.repositories.map(repo=>ui`<option value="${html(repo)}">${html(repo)}</option>`).join('')}</select></div>`,t('Verifica accesso'),data=>mutation('inspect',{connectionId:item.id,scopeId:data.get('scopeId'),repository:data.get('repository')}),{after:result=>{view={kind:'inspection'};languageView=()=>showInspection(result);showInspection(result);}});}
  function showInspection(result){shell(t('Accesso in lettura verificato'),ui`<div class="ops-task-body"><p>GitHub ha risposto alla lettura del repository autorizzato.</p>${result?.defaultBranch?ui`<p>Ramo predefinito: <code>${html(result.defaultBranch)}</code></p>`:''}<p class="github-notice">Questa lettura non verifica i permessi di scrittura né la compatibilità del computer che eseguirà gli incarichi.</p></div>`);}
  function disconnect(item){languageView=()=>disconnect(item);form(t('Scollega GitHub'),ui`<p><strong>${html(item.name)}</strong></p><p>Rimuove la credenziale dallo studio e impedisce nuovi accessi con questo collegamento. Le PR già pubblicate e le fonti già acquisite restano disponibili.</p>`,t('Scollega'),()=>mutation('disconnect',{id:item.id,expectedVersion:item.version}),{after:()=>toast(t('Collegamento rimosso dallo studio.'))});}
  function importFile(){languageView=()=>importFile();const scopeId=context.scopeId;if(!eligible(scopeId).length){toast(t('Collega GitHub e autorizza questo ambito prima di acquisire un file.'));return;}form(t('Acquisisci un file da GitHub'),ui`<p class="ops-form-intro">Destinazione: <strong>${html(scopeName(scopeId))}</strong>. Il contenuto verrà conservato come fonte con riferimento al commit.</p>${targetFields({scopeId})}${field(t('Ramo, tag o commit da leggere'),'ref','main',{max:200})}${field(t('Percorso del file nel repository'),'path','README.md',{max:1000})}${field(t('Titolo della fonte · facoltativo'),'title','',{required:false,max:200})}<p class="github-notice">Il file resta nell’ambito scelto e può entrare nel contesto dei servizi AI autorizzati per quell’ambito. Acquisisci soltanto il materiale che vuoi usare nello studio.</p>`,t('Leggi e acquisisci il file'),async data=>request('/api/sources',{action:'importGitHub',payload:{scopeId,connectionId:data.get('connectionId'),repository:data.get('repository'),ref:data.get('ref').trim(),path:data.get('path').trim(),...(data.get('title').trim()?{title:data.get('title').trim()}:{})}}),{after:()=>{onSourcesChanged();toast(ui`Fonte acquisita in ${scopeName(scopeId)}. Apri Fonti per leggerla.`);}});wireTarget();}
  function previewForm(runId){languageView=()=>previewForm(runId);
    const runs=context.runs.filter(run=>approved(run)&&(runId?run.id===runId:context.filter==='all'||run.scopeId===context.scopeId));
    if(!runs.length){toast(t('Prima approva una patch nella scheda Repository.'));return;}
    const first=runs[0];
    form(t('Prepara l’anteprima della PR'),ui`<p class="ops-form-intro">Questa fase legge GitHub e prepara la proposta. La pubblicazione richiede il passaggio successivo.</p><div class="ops-field"><label for="github-run">Patch approvata</label><select id="github-run" name="runId">${runs.map(run=>ui`<option value="${html(run.id)}">${html(run.title)} · ${html(scopeName(run.scopeId))}</option>`).join('')}</select></div><div id="github-target-fields">${targetFields({scopeId:first.scopeId,publish:true})}</div>${field(t('Ramo di destinazione'),'baseBranch','main',{max:200})}${field(t('Titolo della pull request'),'title',first.title,{max:240})}${field(t('Descrizione della pull request'),'body','',{area:true,max:10000,required:false})}<p class="github-notice">Scegli un collegamento con pubblicazione abilitata per l’ambito della patch. L’anteprima controlla che base e contenuto corrispondano alla modifica approvata.</p>`,t('Prepara anteprima'),async data=>{const run=runFor(data.get('runId'));if(!run||!approved(run))throw Error(t('La patch selezionata non è più approvata. Aggiorna gli incarichi.'));if(!data.get('connectionId')||!data.get('repository'))throw Error(t('Manca un collegamento autorizzato alla pubblicazione in questo ambito.'));return mutation('preview',{runId:run.id,connectionId:data.get('connectionId'),repository:data.get('repository'),baseBranch:data.get('baseBranch').trim(),title:data.get('title').trim(),body:data.get('body').trim()});},{after:result=>{const item=publication(result?.id)||result?.publication||result;if(item?.id)showPublication(item.id);else toast(t('Anteprima preparata. Aprila dall’elenco.'));}});
    wireTarget();dialog.querySelector('[name="runId"]').addEventListener('change',event=>{const run=runFor(event.target.value);dialog.querySelector('#github-target-fields').innerHTML=targetFields({scopeId:run.scopeId,publish:true});dialog.querySelector('[name="title"]').value=run.title;wireTarget();});
  }
  function showPublication(id){languageView=()=>showPublication(id);const item=publication(id);if(!item)return;view={kind:'publication',id};const url=safeUrl(item.url);shell(item.title,ui`<div class="ops-task-body github-preview"><span class="github-state${item.status==='uncertain'||item.baseChanged||item.reviewRequired?' is-warning':''}">${html(item.baseChanged||item.reviewRequired?t('PR da rivedere'):t(states[item.status]||item.status))}</span><dl><div><dt>Repository</dt><dd>${html(item.repository)}</dd></div><div><dt>Ambito</dt><dd>${html(scopeName(item.scopeId))}</dd></div><div><dt>Destinazione</dt><dd>${html(item.baseBranch)}</dd></div><div><dt>Commit di base</dt><dd><code>${html(item.baseCommit)}</code></dd></div><div><dt>Ramo dedicato</dt><dd><code>${html(item.branch)}</code></dd></div><div><dt>Impronta della patch approvata</dt><dd><code>${html(item.patchHash)}</code></dd></div></dl><section><h3>Descrizione pubblicata</h3><p class="github-body">${html(item.body||t('Nessuna descrizione aggiuntiva.'))}</p></section><section><h3>File interessati</h3><ul class="github-file-list">${(item.files||[]).map(file=>ui`<li><code>${html(typeof file==='string'?file:file.path)}</code>${typeof file==='object'?ui`<span>${html(file.status||'')} ${Number.isFinite(file.additions)?`+${file.additions}`:''} ${Number.isFinite(file.deletions)?`−${file.deletions}`:''}</span>`:''}</li>`).join('')}</ul></section><a class="ops-text-button" href="/api/repositories/patch?id=${encodeURIComponent(item.runId)}" download>Scarica la patch approvata</a>${item.baseChanged?ui`<p class="github-notice">Il ramo di destinazione è avanzato durante la pubblicazione. La patch approvata è conservata, ma i controlli non coprono la nuova base${item.actualBaseCommit?` (${html(item.actualBaseCommit)})`:''}. Rivedi la PR prima di unire le modifiche.</p>`:''}${item.error?ui`<p class="github-notice is-error" role="alert">${html(typeof item.error==='string'?item.error:item.error.message||t('L’esito richiede una verifica.'))}</p>`:''}${item.status==='preview'?ui('<p class="github-notice">Pubblicando invii queste modifiche a GitHub e crei una pull request in bozza. Il server verifica di nuovo la patch approvata e il ramo di base.</p>'):item.status==='uncertain'||item.status==='publishing'?ui('<p class="github-notice">La risposta non basta a stabilire l’esito. Verifica su GitHub con il pulsante dedicato prima di qualsiasi nuova pubblicazione.</p>'):''}${url?ui`<a class="ops-button is-primary github-pr-link" href="${html(url)}" target="_blank" rel="noopener noreferrer">Apri la PR su GitHub ↗</a>`:''}</div>`,ui`<button type="button" class="ops-button" data-github-close>Chiudi</button>${item.status==='preview'?ui`<button type="button" class="ops-button is-primary" data-github-action="publish" data-id="${html(id)}" data-github-mutation>Pubblica PR in bozza</button>`:['uncertain','publishing'].includes(item.status)?ui`<button type="button" class="ops-button" data-github-action="reconcile" data-id="${html(id)}" data-github-mutation>Verifica esito su GitHub</button>`:''}`);}
  async function publishAction(action,id){const item=publication(id);if(!item||locked())return;saving=true;locks();try{await mutation(action,{id:item.id,expectedVersion:item.version});saving=false;showPublication(id);}catch(e){toast(e.message);error=e.message;saving=false;await load();if(!disposed)showPublication(id);}finally{saving=false;locks();}}
  function click(event){if(event.target.closest('[data-github-close]')){if(!saving)dialog.close();return;}const button=event.target.closest('[data-github-action]');if(!button||button.disabled)return;const {githubAction:action,id}=button.dataset;if(action==='reload'){void load();return;}if(action==='publication'){showPublication(id);return;}if(locked())return;if(action==='connect')edit();if(action==='edit'&&connection(id))edit(connection(id));if(action==='inspect'&&connection(id))inspect(connection(id));if(action==='disconnect'&&connection(id))disconnect(connection(id));if(action==='import')importFile();if(action==='preview')previewForm();if(['publish','reconcile'].includes(action))void publishAction(action,id);}
  const stopLanguage=onLanguageChange(()=>{
    if(disposed)return;render();if(!dialog.open||saving||!languageView)return;
    const fields=[...dialog.querySelectorAll('input,textarea,select')].map(node=>({name:node.name,value:node.value,checked:node.checked,type:node.type}));
    const get=name=>fields.find(item=>item.name===name)?.value;
    const box=dialog.querySelector('.ops-form-error'),errorText=box&&!box.hidden?box.textContent:null;
    languageView();
    const run=runFor(get('runId'));if(run&&dialog.querySelector('#github-target-fields')){dialog.querySelector('[name="runId"]').value=run.id;dialog.querySelector('#github-target-fields').innerHTML=targetFields({scopeId:run.scopeId,publish:true,chosen:get('connectionId')});wireTarget();}
    const selectedConnection=connection(get('connectionId'));if(selectedConnection&&dialog.querySelector('#github-repository'))dialog.querySelector('#github-repository').innerHTML=selectedConnection.repositories.map(repo=>ui`<option value="${html(repo)}">${html(repo)}</option>`).join('');
    const used=new Map();for(const item of fields){const index=used.get(item.name)||0;used.set(item.name,index+1);const node=[...dialog.querySelectorAll('input,textarea,select')].filter(el=>el.name===item.name)[index];if(!node)continue;if(node.type==='checkbox'||node.type==='radio')node.checked=item.checked;else node.value=item.value;}
    if(errorText){const error=dialog.querySelector('.ops-form-error');if(error){error.textContent=errorText;error.hidden=false;}}
    locks();
  });
  host.addEventListener('click',click);dialog.addEventListener('click',click);dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});dialog.addEventListener('close',()=>{if(!dialog.open){view=null;dialog.querySelectorAll('[data-github-secret]').forEach(input=>input.value='');}});
  function expire(){disposed=true;generation++;controllers.forEach(controller=>controller.abort());snapshot={connections:[],publications:[]};dialog.close();dialog.replaceChildren();host.replaceChildren();}
  window.addEventListener('studio-session-expired',expire);
  return {load,setContext(value){const changed=value.scopeId&&value.scopeId!==context.scopeId;context={...context,...value};if(changed&&dialog.open&&!saving)dialog.close();render();},setVisible(value){visible=Boolean(value);host.hidden=!visible;render();if(visible&&!loaded&&!loading)void load();},setBusy(value){busy=Boolean(value);locks();},async open({runId}={}){if(!loaded)await load();if(!locked())previewForm(runId);},dispose(){stopLanguage();expire();host.removeEventListener('click',click);window.removeEventListener('studio-session-expired',expire);dialog.remove();}};
}
